//! Lifecycle parity against the SAGE mutation oracle
//! (`tests/fixtures/oracle-mutations/{delete-recover,hygiene}.json`,
//! generated by `scripts/oracle/build-mutation-fixtures.ts`).
//!
//! Each scenario is replayed on a fresh managed store with the oracle's
//! clock values, then the observable state after every step is compared:
//! per labelled memory `status`, `revision`, `supersedes`, `supersededBy`,
//! `contradicts`, `contextPolicy`, `staleReason`, `tags`; candidate
//! reasons/targets/actions; hygiene/backfill report counters; and the
//! audit events the step wrote.
//!
//! Documented gaps (not compared):
//! * Timestamps other than the ones that drive day-based rules.
//! * `rememberSage` audit events: the native remember writes
//!   `memory.accepted`/`memory.merged` audit rows; the baseline writes none
//!   (events only). Audit comparison therefore skips remember steps.
//! * Error message text: errors are compared by outcome (refused vs
//!   accepted), because WrongMemory maps them to typed codes.
//! * Field-level audit `details` beyond event names and memory ids.

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

use rusqlite::Connection;
use serde_json::{Value, json};
use wrongmemory_contracts::{MemorySource, RememberParams};
use wrongmemory_storage::hygiene::HygieneOptions;
use wrongmemory_storage::recovery::BackfillFilter;
use wrongmemory_storage::{MutationCtx, SageStore};

fn fixture(name: &str) -> Value {
    let p = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../tests/fixtures/oracle-mutations")
        .join(format!("{name}.json"));
    serde_json::from_str(&std::fs::read_to_string(p).unwrap()).unwrap()
}

fn ctx(now: &str, session: Option<&str>) -> MutationCtx {
    MutationCtx {
        principal_id: "host".into(),
        client_label: "oracle-replay".into(),
        session_id: session.map(str::to_string),
        idempotency_key: None,
        now_iso: now.into(),
    }
}

struct Replay {
    _tmp: tempfile::TempDir,
    root: PathBuf,
    db: PathBuf,
    store: SageStore,
    /// label -> real id
    ids: BTreeMap<String, String>,
    audit_mark: i64,
}

impl Replay {
    fn new() -> Self {
        let tmp = tempfile::tempdir().unwrap();
        let root = tmp.path().join("project");
        std::fs::create_dir_all(root.join("src")).unwrap();
        let db = tmp.path().join("store").join("sage.db");
        SageStore::create_managed(&db, "2026-11-01T00:00:00.000Z").unwrap();
        let (store, _) =
            SageStore::open(&db, true, Some(root.clone()), "2026-11-01T00:00:00.000Z").unwrap();
        Self {
            _tmp: tmp,
            root,
            db,
            store,
            ids: BTreeMap::new(),
            audit_mark: 0,
        }
    }

    fn label_of(&self, real: &str) -> String {
        self.ids
            .iter()
            .find(|(_, v)| *v == real)
            .map(|(k, _)| k.clone())
            .unwrap_or_else(|| real.to_string())
    }

    /// Fixture id (`<id:x>`, `mem_<id:x>`, `01...`) -> label.
    fn fixture_label(id: &str) -> String {
        let id = id.strip_prefix("mem_").unwrap_or(id);
        id.strip_prefix("<id:")
            .and_then(|s| s.strip_suffix('>'))
            .map(str::to_string)
            .unwrap_or_else(|| id.to_string())
    }

    fn real(&self, fixture_id: &str) -> String {
        let l = Self::fixture_label(fixture_id);
        self.ids.get(&l).cloned().unwrap_or(l)
    }

    fn conn(&self) -> Connection {
        Connection::open(&self.db).unwrap()
    }

    fn new_audit_events(&mut self) -> Vec<String> {
        let c = self.conn();
        let rows: Vec<(i64, String)> = c
            .prepare("SELECT id, event FROM audit_log WHERE id > ?1 ORDER BY id")
            .unwrap()
            .query_map([self.audit_mark], |r| Ok((r.get(0)?, r.get(1)?)))
            .unwrap()
            .collect::<Result<_, _>>()
            .unwrap();
        if let Some((last, _)) = rows.last() {
            self.audit_mark = *last;
        }
        rows.into_iter().map(|(_, e)| e).collect()
    }

    fn map_ids(&self, v: &Value) -> Value {
        match v {
            Value::String(s) => json!(self.label_of(s)),
            Value::Array(a) => Value::Array(a.iter().map(|x| self.map_ids(x)).collect()),
            other => other.clone(),
        }
    }

    /// Compare labelled memory state with the oracle's state after a step.
    fn compare_state(&self, step: &str, state: &Value) -> Vec<String> {
        let mut diffs = Vec::new();
        let c = self.conn();
        let mine: BTreeMap<String, Value> = c
            .prepare("SELECT id, data FROM memories")
            .unwrap()
            .query_map([], |r| Ok((r.get::<_, String>(0)?, r.get::<_, String>(1)?)))
            .unwrap()
            .map(|r| {
                let (id, d) = r.unwrap();
                (self.label_of(&id), serde_json::from_str(&d).unwrap())
            })
            .collect();
        let oracle = state["memories"].as_array().unwrap();
        if oracle.len() != mine.len() {
            diffs.push(format!(
                "{step}: memory count oracle={} ours={}",
                oracle.len(),
                mine.len()
            ));
        }
        for m in oracle {
            let d = &m["data"];
            let label = Self::fixture_label(d["id"].as_str().unwrap());
            let Some(ours) = mine.get(&label) else {
                diffs.push(format!("{step}: missing memory {label}"));
                continue;
            };
            for key in [
                "status",
                "revision",
                "supersedes",
                "supersededBy",
                "contradicts",
                "contextPolicy",
                "staleReason",
                "tags",
                "freshness",
            ] {
                let want = match &d[key] {
                    Value::String(s) if key == "supersededBy" => json!(Self::fixture_label(s)),
                    Value::Array(a) if key != "tags" => Value::Array(
                        a.iter()
                            .map(|x| json!(Self::fixture_label(x.as_str().unwrap())))
                            .collect(),
                    ),
                    other => other.clone(),
                };
                let got = if key == "tags" {
                    ours[key].clone()
                } else {
                    self.map_ids(&ours[key])
                };
                let same = match (&want, &got) {
                    (Value::Number(a), Value::Number(b)) => a.as_f64() == b.as_f64(),
                    // Empty array vs absent: baseline drops cleaned arrays
                    // only by `undefined`; treat [] and absent as equal.
                    (Value::Null, Value::Array(a)) | (Value::Array(a), Value::Null) => a.is_empty(),
                    (a, b) => a == b,
                };
                if !same {
                    diffs.push(format!("{step}: {label}.{key} oracle={want} ours={got}"));
                }
            }
        }
        diffs
    }

    fn compare_candidates(&self, step: &str, state: &Value) -> Vec<String> {
        let c = self.conn();
        let mut mine: Vec<String> = c
            .prepare("SELECT data FROM candidates")
            .unwrap()
            .query_map([], |r| r.get::<_, String>(0))
            .unwrap()
            .map(|d| {
                let v: Value = serde_json::from_str(&d.unwrap()).unwrap();
                self.candidate_key(&v, false)
            })
            .collect();
        let mut want: Vec<String> = state["candidates"]
            .as_array()
            .unwrap()
            .iter()
            .map(|cand| self.candidate_key(&cand["data"], true))
            .collect();
        mine.sort();
        want.sort();
        if mine != want {
            vec![format!("{step}: candidates oracle={want:?} ours={mine:?}")]
        } else {
            vec![]
        }
    }

    fn candidate_key(&self, v: &Value, fixture: bool) -> String {
        let lbl = |s: &str| {
            if fixture {
                Self::fixture_label(s)
            } else {
                self.label_of(s)
            }
        };
        let target = v["targetMemoryId"].as_str().map(lbl).unwrap_or_default();
        let mut reason = v["reviewReason"].as_str().unwrap_or("").to_string();
        if let Some(rest) = reason.strip_prefix("Possible contradiction with memory ") {
            reason = format!("Possible contradiction with memory {}", lbl(rest));
        }
        format!(
            "{}|{}|{}|{}|{}|{}|{}",
            v["status"].as_str().unwrap_or(""),
            v["kind"].as_str().unwrap_or(""),
            target,
            reason,
            v["suggestedAction"].as_str().unwrap_or(""),
            v["confidence"],
            v["importance"]
        )
    }
}

fn remember_params(input: &Value) -> (RememberParams, Option<String>) {
    let mut p: RememberParams = serde_json::from_value({
        let mut i = input.clone();
        i.as_object_mut().unwrap().remove("ownerSessionId");
        i
    })
    .unwrap();
    if p.sources.is_empty() {
        p.sources = vec![MemorySource {
            kind: "user".into(),
            ..Default::default()
        }];
    }
    (p, input["ownerSessionId"].as_str().map(str::to_string))
}

fn assert_no_diffs(diffs: Vec<String>) {
    assert!(
        diffs.is_empty(),
        "oracle differences:\n{}",
        diffs.join("\n")
    );
}

#[test]
fn delete_recover_scenario_matches_oracle() {
    let f = fixture("delete-recover");
    let mut r = Replay::new();
    let mut clock = "2026-11-01T00:01:00.000Z".to_string();
    let mut diffs = Vec::new();
    for st in f["steps"].as_array().unwrap() {
        let step = st["step"].as_str().unwrap();
        let call = &st["call"];
        let input = &call["input"];
        let method = call["method"].as_str().unwrap();
        // Advance the clock like the oracle (one tick per step); prefer the
        // oracle's own stamps when the result carries one.
        let t = st["result"]["updatedAt"]
            .as_str()
            .or_else(|| st["result"]["startedAt"].as_str())
            .map(str::to_string);
        clock = t.unwrap_or_else(|| bump_second(&clock));
        let c = ctx(&clock, None);
        let mut is_remember = false;
        let outcome: Result<Value, String> = match method {
            "rememberSage" => {
                is_remember = true;
                let mut inp = input.clone();
                for k in ["supersedes", "contradicts"] {
                    if let Some(a) = inp.get(k).cloned() {
                        inp[k] = json!(
                            a.as_array()
                                .unwrap()
                                .iter()
                                .map(|x| r.real(x.as_str().unwrap()))
                                .collect::<Vec<_>>()
                        );
                    }
                }
                let (p, _) = remember_params(&inp);
                let out = r.store.remember(&p, &c).map_err(|e| e.message);
                if let Ok(o) = &out {
                    let label = Replay::fixture_label(st["result"]["id"].as_str().unwrap());
                    r.ids.insert(label, o.id.clone());
                }
                out.map(|o| o.record)
            }
            "deleteSage" => {
                let id = r.real(input["id"].as_str().unwrap());
                let force = input["options"]["force"].as_bool().unwrap_or(false);
                let never = input["options"]["neverInject"].as_bool().unwrap_or(false);
                let reason = input["reason"].as_str().unwrap_or("deleted");
                r.store
                    .delete(&id, reason, force, never, &c, true)
                    .map(|o| o.record)
                    .map_err(|e| e.message)
            }
            "recoverSage" => {
                let id = r.real(input["id"].as_str().unwrap());
                r.store
                    .recover(&id, None, &c)
                    .map(|m| serde_json::to_value(m).unwrap())
                    .map_err(|e| e.message)
            }
            "backfillRecoverable" => {
                let dry = input["dryRun"].as_bool().unwrap_or(true);
                let rep = r
                    .store
                    .backfill_recoverable(&BackfillFilter::default(), dry, &c)
                    .unwrap();
                for rec in &rep.recoverable_records {
                    if let Some(new_id) = &rec.new_active_id {
                        let base = r.label_of(&rec.original_id);
                        r.ids.insert(format!("{base}Backfilled"), new_id.clone());
                    }
                }
                let want = &st["result"];
                for k in ["examined", "recoverable", "recovered", "skipped"] {
                    let got = serde_json::to_value(&rep).unwrap()[k].clone();
                    if want[k] != got {
                        diffs.push(format!("{step}: report.{k} oracle={} ours={got}", want[k]));
                    }
                }
                let reasons = |v: &Value| -> Vec<String> {
                    v["skippedRecords"]
                        .as_array()
                        .unwrap()
                        .iter()
                        .map(|x| x["reason"].as_str().unwrap().to_string())
                        .collect()
                };
                if reasons(want) != reasons(&serde_json::to_value(&rep).unwrap()) {
                    diffs.push(format!("{step}: skip reasons differ"));
                }
                Ok(Value::Null)
            }
            "getSage" => {
                let id = r.real(input["id"].as_str().unwrap());
                Ok(serde_json::to_value(r.store.get(&id, &Default::default()).unwrap()).unwrap())
            }
            other => panic!("unhandled oracle method {other}"),
        };
        let oracle_failed =
            st.get("error").is_some() || (method == "recoverSage" && st["result"].is_null());
        if oracle_failed != outcome.is_err() {
            diffs.push(format!(
                "{step}: oracle failed={oracle_failed} ours={outcome:?}"
            ));
        }
        if method == "recoverSage"
            && let (Ok(got), Some(want)) = (&outcome, st["result"]["id"].as_str())
        {
            let got_label = r.label_of(got["id"].as_str().unwrap());
            if got_label != Replay::fixture_label(want)
                && !(want.starts_with("mem_") && got_label.ends_with("Backfilled"))
            {
                diffs.push(format!(
                    "{step}: recovered id oracle={want} ours={got_label}"
                ));
            }
        }
        diffs.extend(r.compare_state(step, &st["state"]));
        let events = r.new_audit_events();
        if !is_remember {
            let want: Vec<String> = st["state"]["auditEvents"]
                .as_array()
                .map(|a| {
                    a.iter()
                        .map(|e| e["event"].as_str().unwrap().to_string())
                        .collect()
                })
                .unwrap_or_default();
            if want != events {
                diffs.push(format!("{step}: audit oracle={want:?} ours={events:?}"));
            }
        }
    }
    assert_no_diffs(diffs);
}

fn bump_second(iso: &str) -> String {
    let ms = wrongmemory_storage::text::parse_iso_ms(iso).unwrap() + 1000;
    iso_from_ms(ms)
}

fn iso_from_ms(ms: i64) -> String {
    let secs = ms.div_euclid(1000);
    let millis = ms.rem_euclid(1000);
    let days = secs.div_euclid(86_400);
    let tod = secs.rem_euclid(86_400);
    let z = days + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z.rem_euclid(146_097);
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let y = yoe + era * 400 + if m <= 2 { 1 } else { 0 };
    format!(
        "{y:04}-{m:02}-{d:02}T{:02}:{:02}:{:02}.{millis:03}Z",
        tod / 3600,
        (tod % 3600) / 60,
        tod % 60
    )
}

#[test]
fn hygiene_scenario_matches_oracle() {
    let f = fixture("hygiene");
    let mut r = Replay::new();
    std::fs::write(
        r.root.join("src/present.ts"),
        "export const present = true;\n",
    )
    .unwrap();
    std::fs::write(r.root.join("src/gone.ts"), "temporary\n").unwrap();
    let mut diffs = Vec::new();
    let mut last_created = String::new();
    for st in f["steps"].as_array().unwrap() {
        let step = st["step"].as_str().unwrap();
        let call = &st["call"];
        let input = &call["input"];
        match call["method"].as_str().unwrap() {
            "rememberSage" => {
                let now = st["result"]["createdAt"].as_str().unwrap().to_string();
                let (p, session) = remember_params(input);
                let out = r
                    .store
                    .remember(&p, &ctx(&now, session.as_deref()))
                    .unwrap();
                r.ids.insert(
                    Replay::fixture_label(st["result"]["id"].as_str().unwrap()),
                    out.id,
                );
                last_created = now;
                let _ = r.new_audit_events(); // remember audit differs (module docs)
            }
            "hygiene" => {
                if step == "hygiene-default" {
                    // Oracle setup between steps: raw exact duplicate of dupA,
                    // then src/gone.ts removed (see build-mutation-fixtures.ts).
                    insert_raw_duplicate(&r, &last_created);
                    std::fs::remove_file(r.root.join("src/gone.ts")).unwrap();
                }
                if step == "hygiene-reactivates-verification-stale" {
                    std::fs::write(r.root.join("src/gone.ts"), "restored\n").unwrap();
                }
                let now = st["result"]["startedAt"].as_str().unwrap();
                let opts: HygieneOptions = serde_json::from_value(input.clone()).unwrap();
                let report = r.store.hygiene(&opts, &ctx(now, None)).unwrap();
                let got = serde_json::to_value(&report).unwrap();
                for k in [
                    "examined",
                    "deduplicated",
                    "superseded",
                    "contradicted",
                    "staled",
                    "reviewCandidatesCreated",
                    "deleted",
                    "purgedDeleted",
                    "verified",
                    "reactivated",
                    "transitiveMerges",
                ] {
                    if st["result"][k] != got[k] {
                        diffs.push(format!(
                            "{step}: report.{k} oracle={} ours={}",
                            st["result"][k], got[k]
                        ));
                    }
                }
                let want: Vec<String> = st["state"]["auditEvents"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|e| e["event"].as_str().unwrap().to_string())
                    .collect();
                let events = r.new_audit_events();
                if want != events {
                    diffs.push(format!("{step}: audit oracle={want:?} ours={events:?}"));
                }
                diffs.extend(r.compare_candidates(step, &st["state"]));
            }
            other => panic!("unhandled oracle method {other}"),
        }
        diffs.extend(r.compare_state(step, &st["state"]));
    }
    assert_no_diffs(diffs);
}

fn insert_raw_duplicate(r: &Replay, created_at: &str) {
    let c = r.conn();
    let dup_a = &r.ids["dupA"];
    let data: String = c
        .query_row("SELECT data FROM memories WHERE id = ?1", [dup_a], |x| {
            x.get(0)
        })
        .unwrap();
    let mut copy: Value = serde_json::from_str(&data).unwrap();
    copy["id"] = json!("01DUPLICATECOPY00000000000B");
    copy["importance"] = json!(0.7);
    copy["createdAt"] = json!(created_at);
    c.execute(
        "INSERT INTO memories (id, data, status, kind, scope, legacy_scope, importance, confidence, freshness,
           updated_at, created_at, audience, tags, owner_session_id, canonical_text)
         VALUES (?1, ?2, 'active', ?3, ?4, 'project-memory', ?5, ?6, ?7, ?8, ?9, NULL, ?10, NULL, ?11)",
        rusqlite::params![
            "01DUPLICATECOPY00000000000B",
            copy.to_string(),
            copy["kind"].as_str(),
            copy["scope"].as_str(),
            0.7,
            copy["confidence"].as_f64(),
            copy["freshness"].as_f64(),
            copy["updatedAt"].as_str(),
            created_at,
            copy["tags"].to_string(),
            "logs are shipped to the central collector every minute.",
        ],
    )
    .unwrap();
}

// ─── Unit-level checks ───────────────────────────────────────────────────

fn store_with(texts: &[(&str, &str)]) -> (Replay, Vec<String>) {
    let mut r = Replay::new();
    let mut ids = Vec::new();
    for (i, (text, scope)) in texts.iter().enumerate() {
        let p = RememberParams {
            text: (*text).into(),
            scope: Some((*scope).into()),
            ..Default::default()
        };
        let now = format!("2026-11-01T00:00:{:02}.000Z", i + 1);
        let session = (*scope == "session").then_some("s1");
        ids.push(r.store.remember(&p, &ctx(&now, session)).unwrap().id);
    }
    (r, ids)
}

#[test]
fn backfill_skip_reasons_follow_baseline_order() {
    let (mut r, ids) = store_with(&[
        ("Alpha service owns the ledger tables.", "project"),
        ("Beta service reads the ledger through views.", "project"),
        ("Gamma jobs rotate the ledger archive weekly.", "user"),
    ]);
    let now = "2026-11-02T00:00:00.000Z";
    for id in &ids {
        r.store
            .delete(id, "test", true, false, &ctx(now, None), true)
            .unwrap();
    }
    // A live duplicate of Beta makes its tombstone `duplicate_active`.
    r.store
        .remember(
            &RememberParams {
                text: "Beta service reads the ledger through views.".into(),
                ..Default::default()
            },
            &ctx("2026-11-02T00:00:01.000Z", None),
        )
        .unwrap();
    let filter = BackfillFilter {
        scopes: Some(vec!["project".into()]),
        ..Default::default()
    };
    let rep = r
        .store
        .backfill_recoverable(&filter, true, &ctx(now, None))
        .unwrap();
    let reasons: BTreeMap<String, String> = rep
        .skipped_records
        .iter()
        .map(|s| (s.original_id.clone(), s.reason.clone()))
        .collect();
    assert_eq!(reasons[&ids[1]], "duplicate_active");
    assert_eq!(reasons[&ids[2]], "filter_scopes");
    assert_eq!(rep.recoverable, 1);
    let only = BackfillFilter {
        ids: Some(vec![ids[0].clone()]),
        ..Default::default()
    };
    let rep = r
        .store
        .backfill_recoverable(&only, false, &ctx(now, None))
        .unwrap();
    assert_eq!(rep.recovered, 1);
    assert_eq!(rep.by_reason["filter_ids"], 2);
    let again = r
        .store
        .backfill_recoverable(&only, true, &ctx(now, None))
        .unwrap();
    for rec in &again.skipped_records {
        let want = if rec.original_id == ids[0] {
            "already_recovered"
        } else {
            "filter_ids"
        };
        assert_eq!(rec.reason, want, "{}", rec.original_id);
    }
    // Recovering the original now returns the backfilled successor.
    let head = r.store.recover(&ids[0], None, &ctx(now, None)).unwrap();
    assert!(head.id.starts_with("mem_"));
    assert!(head.tags.contains(&"backfill:recovered".to_string()));
}

#[test]
fn hygiene_never_reactivates_manual_stale_and_dry_run_writes_nothing() {
    let mut r = Replay::new();
    std::fs::write(r.root.join("src/a.ts"), "x").unwrap();
    let p = RememberParams {
        text: "a.ts exports the router helpers for the app.".into(),
        anchors: vec![wrongmemory_contracts::MemoryAnchor {
            kind: "file".into(),
            path: Some("src/a.ts".into()),
            ..Default::default()
        }],
        ..Default::default()
    };
    let id = r
        .store
        .remember(&p, &ctx("2026-11-01T00:00:01.000Z", None))
        .unwrap()
        .id;
    let mut patch = serde_json::Map::new();
    patch.insert("status".into(), json!("stale"));
    r.store
        .update(&id, &patch, &ctx("2026-11-01T00:00:02.000Z", None), false)
        .unwrap();
    let before = r.store.get(&id, &Default::default()).unwrap().unwrap();
    assert_eq!(before.stale_reason.as_deref(), Some("manual"));
    let rep = r
        .store
        .hygiene(
            &HygieneOptions::default(),
            &ctx("2026-11-02T00:00:00.000Z", None),
        )
        .unwrap();
    assert_eq!(rep.reactivated, 0);
    let after = r.store.get(&id, &Default::default()).unwrap().unwrap();
    assert_eq!(
        after.status, "stale",
        "manual retirement survives verification"
    );

    // Verification-stale memory with the file back: dry run reports the
    // reactivation but leaves the row untouched.
    std::fs::remove_file(r.root.join("src/a.ts")).unwrap();
    let p2 = RememberParams {
        text: "b.ts holds the queue adapter for background jobs.".into(),
        anchors: vec![wrongmemory_contracts::MemoryAnchor {
            kind: "file".into(),
            path: Some("src/b.ts".into()),
            ..Default::default()
        }],
        ..Default::default()
    };
    std::fs::write(r.root.join("src/b.ts"), "x").unwrap();
    let b = r
        .store
        .remember(&p2, &ctx("2026-11-03T00:00:00.000Z", None))
        .unwrap()
        .id;
    std::fs::remove_file(r.root.join("src/b.ts")).unwrap();
    let rep = r
        .store
        .hygiene(
            &HygieneOptions::default(),
            &ctx("2026-11-03T00:00:01.000Z", None),
        )
        .unwrap();
    assert_eq!(rep.staled, 1);
    let stale = r.store.get(&b, &Default::default()).unwrap().unwrap();
    assert_eq!(stale.stale_reason.as_deref(), Some("verification"));
    std::fs::write(r.root.join("src/b.ts"), "x").unwrap();
    let dry = HygieneOptions {
        dry_run: true,
        ..Default::default()
    };
    let rep = r
        .store
        .hygiene(&dry, &ctx("2026-11-03T00:00:02.000Z", None))
        .unwrap();
    assert!(rep.dry_run);
    assert_eq!(rep.reactivated, 1);
    assert_eq!(
        r.store
            .get(&b, &Default::default())
            .unwrap()
            .unwrap()
            .status,
        "stale"
    );
    let rep = r
        .store
        .hygiene(
            &HygieneOptions::default(),
            &ctx("2026-11-03T00:00:03.000Z", None),
        )
        .unwrap();
    assert_eq!(rep.reactivated, 1);
    assert_eq!(
        r.store
            .get(&b, &Default::default())
            .unwrap()
            .unwrap()
            .status,
        "active"
    );
}

#[test]
fn verification_rejects_paths_escaping_the_root() {
    let mut r = Replay::new();
    // A real file outside the project root.
    let outside = r.root.parent().unwrap().join("outside.ts");
    std::fs::write(&outside, "x").unwrap();
    let p = RememberParams {
        text: "outside.ts is referenced through a parent path escape.".into(),
        anchors: vec![wrongmemory_contracts::MemoryAnchor {
            kind: "file".into(),
            path: Some("../outside.ts".into()),
            ..Default::default()
        }],
        ..Default::default()
    };
    let id = r
        .store
        .remember(&p, &ctx("2026-11-01T00:00:01.000Z", None))
        .unwrap()
        .id;
    let rep = r
        .store
        .hygiene(
            &HygieneOptions::default(),
            &ctx("2026-11-01T00:00:02.000Z", None),
        )
        .unwrap();
    assert_eq!(
        rep.staled, 1,
        "an escaping anchor is never treated as present"
    );
    assert_eq!(
        r.store
            .get(&id, &Default::default())
            .unwrap()
            .unwrap()
            .status,
        "stale"
    );
}

/// Legacy `forget` / `consolidate` / `clear` against the oracle
/// (`legacy-bulk.json`): per-step memory state (status, revision,
/// relationships, tags), the merged keeper's anchors and sources, returned
/// counts, and audit event names with their `details`.
#[test]
fn legacy_bulk_scenario_matches_oracle() {
    let f = fixture("legacy-bulk");
    let mut r = Replay::new();
    let mut diffs = Vec::new();
    let mut clock = "2026-11-01T00:00:00.000Z".to_string();
    for st in f["steps"].as_array().unwrap() {
        let step = st["step"].as_str().unwrap();
        let input = &st["call"]["input"];
        let method = st["call"]["method"].as_str().unwrap();
        clock = bump_second(&clock);
        let c = ctx(&clock, None);
        let result: Option<Value> = match method {
            "rememberSage" => {
                let mut inp = input.clone();
                if let Some(a) = inp.get("supersedes").cloned() {
                    inp["supersedes"] = json!(
                        a.as_array()
                            .unwrap()
                            .iter()
                            .map(|x| r.real(x.as_str().unwrap()))
                            .collect::<Vec<_>>()
                    );
                }
                let (p, _) = remember_params(&inp);
                let o = r.store.remember(&p, &c).unwrap();
                r.ids.insert(
                    Replay::fixture_label(st["result"]["id"].as_str().unwrap()),
                    o.id,
                );
                r.new_audit_events();
                continue;
            }
            "dump" => None,
            "consolidate" => Some(
                r.store
                    .legacy_consolidate(input["scope"].as_str().unwrap(), &c)
                    .unwrap()
                    .record,
            ),
            "forget" => Some(
                r.store
                    .legacy_forget(
                        input["query"].as_str().unwrap(),
                        input["scope"].as_str().unwrap(),
                        &c,
                    )
                    .unwrap()
                    .record,
            ),
            "clear" => Some(
                r.store
                    .legacy_clear(input["scope"].as_str(), &c)
                    .unwrap()
                    .record,
            ),
            other => panic!("unhandled oracle method {other}"),
        };
        if method == "forget" {
            let got = result.as_ref().unwrap()["removed"].clone();
            if st["result"] != got {
                diffs.push(format!(
                    "{step}: removed oracle={} ours={got}",
                    st["result"]
                ));
            }
        }
        diffs.extend(r.compare_state(step, &st["state"]));
        // Merged keeper contents.
        for m in st["state"]["memories"].as_array().unwrap() {
            let d = &m["data"];
            let label = Replay::fixture_label(d["id"].as_str().unwrap());
            let ours: Value = {
                let c = r.conn();
                let data: String = c
                    .query_row(
                        "SELECT data FROM memories WHERE id = ?1",
                        [r.real(&label)],
                        |row| row.get(0),
                    )
                    .unwrap();
                serde_json::from_str(&data).unwrap()
            };
            for key in ["anchors", "sources"] {
                if d[key] != ours[key] {
                    diffs.push(format!(
                        "{step}: {label}.{key}\n  oracle={}\n  ours  ={}",
                        d[key], ours[key]
                    ));
                }
            }
        }
        // Audit events with their details (memory ids mapped to labels).
        let want: Vec<Value> = st["state"]["auditEvents"]
            .as_array()
            .map(|a| {
                a.iter()
                    .map(|e| {
                        let mut d = e["data"].clone();
                        if let Some(sk) = d["details"]["skipped"].as_array() {
                            d["details"]["skipped"] = json!(
                                sk.iter()
                                    .map(|x| Replay::fixture_label(x.as_str().unwrap()))
                                    .collect::<Vec<_>>()
                            );
                        }
                        json!([e["event"], d])
                    })
                    .collect()
            })
            .unwrap_or_default();
        let got: Vec<Value> = {
            let c = r.conn();
            let rows: Vec<(i64, String, String)> = c
                .prepare("SELECT id, event, data FROM audit_log WHERE id > ?1 ORDER BY id")
                .unwrap()
                .query_map([r.audit_mark], |row| {
                    Ok((row.get(0)?, row.get(1)?, row.get(2)?))
                })
                .unwrap()
                .collect::<Result<_, _>>()
                .unwrap();
            if let Some((last, ..)) = rows.last() {
                r.audit_mark = *last;
            }
            rows.into_iter()
                .map(|(_, e, d)| {
                    let mut d: Value = serde_json::from_str(&d).unwrap();
                    if let Some(sk) = d["details"]["skipped"].as_array() {
                        d["details"]["skipped"] = json!(
                            sk.iter()
                                .map(|x| r.label_of(x.as_str().unwrap()))
                                .collect::<Vec<_>>()
                        );
                    }
                    json!([e, d])
                })
                .collect()
        };
        if want != got {
            diffs.push(format!(
                "{step}: audit\n  oracle={want:?}\n  ours  ={got:?}"
            ));
        }
    }
    assert_no_diffs(diffs);
}

/// `verify` / `verifyForPaths` against the oracle (`verify.json`): per
/// memory the aggregate status, per anchor the status, reason and content
/// hash, then the reconciled state (status, revision, staleReason,
/// freshness). The generator's file edits between steps are replayed here.
#[test]
fn verify_scenario_matches_oracle() {
    let f = fixture("verify");
    let mut r = Replay::new();
    let write = |root: &Path, rel: &str, body: &str| {
        let p = root.join(rel);
        std::fs::create_dir_all(p.parent().unwrap()).unwrap();
        std::fs::write(p, body).unwrap();
    };
    write(
        &r.root,
        "src/app.ts",
        "export function startServer() {}\nconst $ref = 1;\n",
    );
    write(&r.root, "src/lib/util.ts", "export const u = 1;\n");
    write(&r.root, "docs/readme.md", "# readme\n");
    std::fs::create_dir_all(r.root.join(".wrongstack/agents/release-manager")).unwrap();
    let mut diffs = Vec::new();
    let mut clock = "2026-11-01T00:00:00.000Z".to_string();
    for st in f["steps"].as_array().unwrap() {
        let step = st["step"].as_str().unwrap();
        let input = &st["call"]["input"];
        let method = st["call"]["method"].as_str().unwrap();
        clock = bump_second(&clock);
        let c = ctx(&clock, None);
        let results: Option<Vec<Value>> = match method {
            "rememberSage" => {
                let (p, _) = remember_params(input);
                let o = r.store.remember(&p, &c).unwrap();
                r.ids.insert(
                    Replay::fixture_label(st["result"]["id"].as_str().unwrap()),
                    o.id,
                );
                continue;
            }
            "dump" => None,
            "verify" => {
                let id = input["id"].as_str().map(|x| r.real(x));
                Some(r.store.verify(id.as_deref(), &c).unwrap())
            }
            "verifyForPaths" => {
                let paths: Vec<String> = input["paths"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(|p| p.as_str().unwrap().to_string())
                    .collect();
                Some(r.store.verify_for_paths(&paths, &c).unwrap())
            }
            "updateSage" => {
                let id = r.real(input["id"].as_str().unwrap());
                let mut patch = input.as_object().unwrap().clone();
                patch.remove("id");
                // Not an `UpdateSageInput` field: the baseline ignores it and
                // derives `staleReason: manual` from `status: stale` itself.
                patch.remove("staleReason");
                r.store.update(&id, &patch, &c, false).unwrap();
                None
            }
            other => panic!("unhandled oracle method {other}"),
        };
        if let Some(got) = results {
            let shape = |v: &Value, fixture: bool| -> Value {
                json!({
                    "memory": if fixture {
                        Replay::fixture_label(v["memoryId"].as_str().unwrap())
                    } else {
                        r.label_of(v["memoryId"].as_str().unwrap())
                    },
                    "status": v["status"],
                    "anchors": v["anchors"].as_array().unwrap().iter().map(|a| json!([
                        a["status"], a["reason"], a["contentHash"]
                    ])).collect::<Vec<_>>(),
                })
            };
            let want: Vec<Value> = st["result"]
                .as_array()
                .unwrap()
                .iter()
                .map(|v| shape(v, true))
                .collect();
            let got: Vec<Value> = got.iter().map(|v| shape(v, false)).collect();
            if want != got {
                diffs.push(format!(
                    "{step}: results\n  oracle={}\n  ours  ={}",
                    json!(want),
                    json!(got)
                ));
            }
        }
        diffs.extend(r.compare_state(step, &st["state"]));
        // File edits the generator made after these steps.
        match step {
            "verify-all" => std::fs::remove_file(r.root.join("src/app.ts")).unwrap(),
            "verifyForPaths-deleted-file" => {
                write(&r.root, "src/app.ts", "export function startServer() {}\n")
            }
            _ => {}
        }
    }
    assert_no_diffs(diffs);
}
